// Recordatorios: facturas vencidas, y las que vencen en los proximos 3 dias. Solo recordatorios: este flujo
// NO cambia estados de factura. Una factura se recuerda como maximo una vez por dia.
const fecha = hoy();
const limite = sumarDias(fecha, 3);
const recordadas = memoriaLeer('recordadas', {});
const lista = (nombre) => ($(nombre).first().json.contenido ?? []);
const candidatas = [
  ...lista('Facturas vencidas').map((f) => ({ ...f, tipo: 'vencida' })),
  ...lista('Facturas emitidas').filter((f) => f.fecha_vencimiento >= fecha && f.fecha_vencimiento <= limite).map((f) => ({ ...f, tipo: 'por_vencer' })),
  ...lista('Facturas con cobro parcial').filter((f) => f.fecha_vencimiento >= fecha && f.fecha_vencimiento <= limite).map((f) => ({ ...f, tipo: 'por_vencer' })),
].filter((f) => Number(f.saldo) > 0);
const pendientes = candidatas.filter((f) => recordadas[f.id] !== fecha);
const nuevas = {};
for (const f of candidatas) nuevas[f.id] = fecha; // se descarta lo de dias anteriores
memoriaGuardar('recordadas', nuevas);
return pendientes.map((f) => ({ json: f }));

